<?php require_once 'bootstrap.php';$u=require_login();$date=date('Y-m-d');$st=db()->prepare('SELECT * FROM journal_entries WHERE user_sic_id=? AND entry_date=?');$st->execute([$u['sic_id'],$date]);$row=$st->fetch()?:['mood'=>5,'gratitude'=>'','note'=>''];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$m=max(1,min(10,(int)($_POST['mood']??5)));$g=trim($_POST['gratitude']??'');$n=trim($_POST['note']??'');db()->prepare('INSERT INTO journal_entries(sic_id,user_sic_id,entry_date,mood,gratitude,note) VALUES(?,?,?,?,?,?) ON CONFLICT(user_sic_id,entry_date) DO UPDATE SET mood=excluded.mood,gratitude=excluded.gratitude,note=excluded.note,updated_at=CURRENT_TIMESTAMP')->execute([sic_id(),$u['sic_id'],$date,$m,$g,$n]);drx_post($u['sic_id'],null,5,'JOURNAL',true,'journal:'.$u['sic_id'].':'.$date,null,['date'=>$date]);$row=['mood'=>$m,'gratitude'=>$g,'note'=>$n];$msg='Diario salvato. +DRX una sola volta oggi.';} $hist=db()->prepare('SELECT entry_date,mood FROM journal_entries WHERE user_sic_id=? ORDER BY entry_date DESC LIMIT 30');$hist->execute([$u['sic_id']]);$history=array_reverse($hist->fetchAll());$pageTitle='Diario';require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Private Journal</span><h1>Oggi</h1><p>Il diario è personale e privato. Non entra negli insight condivisi in forma identificabile.</p></div></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><section class="card"><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><label>Come sto, da 1 a 10<input type="range" min="1" max="10" name="mood" value="<?=h((string)$row['mood'])?>"></label><label>Una cosa per cui sono grato<textarea name="gratitude" rows="3"><?=h($row['gratitude'])?></textarea></label><label>Scrivi liberamente<textarea name="note" rows="8"><?=h($row['note'])?></textarea></label><button class="btn primary">Salva il mio giorno</button></form></section><section class="card"><h2>Ultimi 30 giorni</h2><div id="moodChart" data-values='<?=h(json_encode($history,JSON_UNESCAPED_UNICODE))?>'></div></section><script>let e=document.getElementById('moodChart'),a=JSON.parse(e.dataset.values||'[]');e.innerHTML=a.length?'<div style="display:flex;align-items:end;gap:3px;height:120px">'+a.map(x=>`<i title="${x.entry_date}: ${x.mood}" style="flex:1;min-width:3px;height:${x.mood*10}%;background:#0EA5E9;border-radius:4px"></i>`).join('')+'</div>':'<p>Nessun dato ancora.</p>';</script><?php require '_footer.php';?>